// The commands the page may call, each with its allow-/deny- permission generated under permissions/autogenerated.
// `permissions/default.toml` grants them all to a window that lists `krizaka:default` in its capability.
const COMMANDS: &[&str] = &[
    "folders",
    "grant_folder",
    "revoke_folder",
    "list_folder",
    "watch_folder",
    "unwatch_folder",
    "secret_get",
    "secret_set",
    "secret_remove",
    "set_menu",
    "take_links",
    "update_channel",
    "set_update_channel",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
